id: {
    let key: Option<String> = match tx.query_row(
        "SELECT idempotency_key FROM financial_mutation_lease \
         WHERE organization_id = ?1 AND conflict_domain = 'invoice_payment' \
         AND logical_resource_id = ?2 AND state = 'held' \
         ORDER BY acquired_ms DESC, id DESC LIMIT 1",
        rusqlite::params![org, &invoice_ref.id],
        |row| row.get(0),
    ) {
        Ok(key) => Some(key),
        Err(rusqlite::Error::QueryReturnedNoRows) => None,
        Err(error) => {
            return Err(PaymentError::Store(format!(
                "read invoice payment fence: {error}"
            )))
        }
    };
    match key {
        Some(key) => {
            operation_resource_id("pay", org, "pay_invoice", &key)
        }
        None => format!("pay_{}", uuid::Uuid::new_v4()),
    }
},
